1	// `andes-sim doctor` -- read-only environment health.
2	//
3	// The four carried-over sections (artifacts, submodules, toolchain, runtime)
4	// plus the Summary line are a faithful C++ port of the Python hsim `cmd_doctor`,
5	// kept byte-identical so the parity flywheel stays green. The detail strings
6	// reference `./hsim build` verbatim from the golden; the F14 name swap renames
7	// them. After Summary the driver appends an `engines:` readout sourced from F2
8	// discovery -- new surface, INFO-tagged, never affecting the exit code (which
9	// stays 1 iff any FAIL row, exactly as the golden).
10	#include <algorithm>
11	#include <cctype>
12	#include <cstdio>
13	#include <cstdlib>
14	#include <filesystem>
15	#include <fstream>
16	#include <string>
17	#include <vector>
18	
19	#include <sys/statvfs.h>
20	#include <unistd.h>
21	
22	#include "cli.hpp"
23	#include "engine_registry.hpp"
24	#include "repo_root.hpp"
25	#include "strutil.hpp"
26	
27	namespace fs = std::filesystem;
28	
29	namespace andes_sim {
30	namespace {
31	
32	// One diagnostic row. status is PASS | FAIL | WARN | INFO; only PASS/FAIL/WARN
33	// feed the summary, and only FAIL gates the exit code.
34	struct Row {
35	  std::string name;
36	  std::string status;
37	  std::string detail;
38	};
39	
40	// Strip every leading and trailing `c` from `s` (mirrors Python str.strip(c)).
41	std::string strip_char(std::string s, char c) {
42	  size_t b = 0, e = s.size();
43	  while (b < e && s[b] == c) ++b;
44	  while (e > b && s[e - 1] == c) --e;
45	  return s.substr(b, e - b);
46	}
47	
48	// --- artifacts --------------------------------------------------------------
49	
50	std::vector<Row> doctor_artifacts() {
51	  const fs::path root = repo_root();
52	  struct A {
53	    const char* label;
54	    const char* env;
55	    fs::path def;
56	  };
57	  // Env overrides match hsim's _ARTIFACT_ENV so a test can simulate a missing
58	  // binary. Order (vsim, qemu, plugin) mirrors the golden's dict order.
59	  const A arts[] = {
60	      {"vsim", "VSIM_BIN", root / "verilator" / "build" / "sim_ax45mpv_premium"},
61	      {"qemu", "VSIM_QEMU", root / "build" / "qemu" / "qemu-system-riscv64"},
62	      {"plugin", "VSIM_PLUGIN", default_plugin_path()},
63	  };
64	  std::vector<Row> rows;
65	  for (const A& a : arts) {
66	    const char* ov = std::getenv(a.env);
67	    fs::path p = (ov && *ov) ? fs::path(ov) : a.def;
68	    if (fs::is_regular_file(p))
69	      rows.push_back({a.label, "PASS", p.string()});
70	    else
71	      rows.push_back(
72	          {a.label, "FAIL", "missing " + p.string() + " -- run ./hsim build"});
73	  }
74	
75	  const fs::path simpoint = root / "tools" / "simpoint" / "bin" / "simpoint";
76	  if (fs::is_regular_file(simpoint))
77	    rows.push_back({"simpoint", "PASS", simpoint.string()});
78	  else
79	    rows.push_back({"simpoint", "FAIL",
80	                    "missing " + simpoint.string() +
81	                        " -- run ./hsim build --what simpoint"});
82	
83	  const fs::path fix = root / "tests" / "fixtures";
84	  size_t elfs = 0;
85	  std::error_code ec;
86	  if (fs::is_directory(fix, ec))
87	    for (const auto& e : fs::directory_iterator(fix, ec))
88	      if (e.path().extension() == ".elf") ++elfs;
89	  if (elfs > 0)
90	    rows.push_back(
91	        {"fixtures", "PASS", std::to_string(elfs) + " ELFs in " + fix.string()});
92	  else
93	    rows.push_back({"fixtures", "FAIL",
94	                    "no *.elf in " + fix.string() +
95	                        " -- run make -C tests/fixtures"});
96	  return rows;
97	}
98	
99	// --- submodules -------------------------------------------------------------
100	
101	std::vector<Row> doctor_submodules() {
102	  const fs::path root = repo_root();
103	  struct M {
104	    const char* name;
105	    fs::path marker;
106	    const char* rel;  // marker, repo-relative (the PASS detail)
107	  };
108	  const M ms[] = {
109	      {"QEMU/", root / "QEMU" / "configure", "QEMU/configure"},
110	      {"verilator/", root / "verilator" / "CMakeLists.txt",
111	       "verilator/CMakeLists.txt"},
112	      {"tools/simpoint/", root / "tools" / "simpoint" / "Makefile",
113	       "tools/simpoint/Makefile"},
114	  };
115	  std::vector<Row> rows;
116	  for (const M& m : ms) {
117	    if (fs::is_regular_file(m.marker))
118	      rows.push_back({m.name, "PASS", m.rel});
119	    else
120	      rows.push_back({m.name, "FAIL",
121	                      "missing " + m.marker.string() +
122	                          " -- run 'git submodule update --init --recursive'"});
123	  }
124	  return rows;
125	}
126	
127	// --- toolchain --------------------------------------------------------------
128	
129	// First PATH directory holding an executable non-directory named `tool`, joined
130	// the way shutil.which reports it (dir + '/' + tool). "" if not found.
131	std::string which(const std::string& tool) {
132	  const char* path = std::getenv("PATH");
133	  if (!path) return "";
134	  const std::string p(path);
135	  for (size_t i = 0; i <= p.size();) {
136	    size_t j = p.find(':', i);
137	    if (j == std::string::npos) j = p.size();
138	    std::string dir = p.substr(i, j - i);
139	    i = j + 1;
140	    if (dir.empty()) continue;
141	    std::string cand = dir.back() == '/' ? dir + tool : dir + "/" + tool;
142	    std::error_code ec;
143	    if (::access(cand.c_str(), X_OK) == 0 && !fs::is_directory(cand, ec))
144	      return cand;
145	  }
146	  return "";
147	}
148	
149	// Match `^\s*(?:export\s+)?HYBRID_TOOLCHAIN\s*=\s*(.+?)\s*$`; on match set `out`
150	// to the value with surrounding whitespace, then double, then single quotes
151	// stripped (mirrors hsim._read_hybrid_toolchain).
152	bool parse_toolchain_line(const std::string& line, std::string& out) {
153	  size_t i = 0, n = line.size();
154	  auto skip_ws = [&] {
155	    while (i < n && std::isspace(static_cast<unsigned char>(line[i]))) ++i;
156	  };
157	  skip_ws();
158	  const std::string kw = "export";
159	  if (line.compare(i, kw.size(), kw) == 0 && i + kw.size() < n &&
160	      std::isspace(static_cast<unsigned char>(line[i + kw.size()]))) {
161	    i += kw.size();
162	    skip_ws();
163	  }
164	  const std::string key = "HYBRID_TOOLCHAIN";
165	  if (line.compare(i, key.size(), key) != 0) return false;
166	  i += key.size();
167	  skip_ws();
168	  if (i >= n || line[i] != '=') return false;
169	  std::string rest = line.substr(i + 1);  // everything after '='
170	  if (rest.empty()) return false;         // regex (.+?) needs >= 1 char
171	  size_t b = 0, e = rest.size();
172	  while (b < e && std::isspace(static_cast<unsigned char>(rest[b]))) ++b;
173	  while (e > b && std::isspace(static_cast<unsigned char>(rest[e - 1]))) --e;
174	  std::string val = strip_char(rest.substr(b, e - b), '"');
175	  out = strip_char(val, '\'');
176	  return true;
177	}
178	
179	// HYBRID_TOOLCHAIN: env first (non-empty wins), else the first matching
180	// assignment in config.env. "" if neither yields a value.
181	std::string read_hybrid_toolchain() {
182	  const char* env = std::getenv("HYBRID_TOOLCHAIN");
183	  if (env && *env) return env;
184	  std::ifstream f(repo_root() / "config.env");
185	  if (!f) return "";
186	  std::string line, val;
187	  while (std::getline(f, line))
188	    if (parse_toolchain_line(line, val)) return val;
189	  return "";
190	}
191	
192	std::vector<Row> doctor_toolchain() {
193	  struct T {
194	    const char* tool;
195	    const char* hint;
196	    bool warn_only;  // a missing podman warns; ninja/make fail
197	  };
198	  const T tools[] = {
199	      {"ninja", "needed by ./hsim build of QEMU", false},
200	      {"make", "needed by ./hsim build of fixtures + simpoint", false},
201	      {"podman", "needed by ./hsim build of vsim (or docker shim)", true},
202	  };
203	  std::vector<Row> rows;
204	  for (const T& t : tools) {
205	    std::string found = which(t.tool);
206	    if (!found.empty())
207	      rows.push_back({t.tool, "PASS", found});
208	    else
209	      rows.push_back({t.tool, t.warn_only ? "WARN" : "FAIL",
210	                      std::string("not on PATH -- ") + t.hint});
211	  }
212	
213	  std::string tc = read_hybrid_toolchain();
214	  if (tc.empty()) {
215	    rows.push_back({"HYBRID_TOOLCHAIN", "WARN",
216	                    "not set -- needed for fixture build (see config.env)"});
217	  } else {
218	    fs::path gcc = fs::path(tc) / "bin" / "riscv64-unknown-elf-gcc";
219	    if (fs::is_regular_file(gcc))
220	      rows.push_back({"riscv64-unknown-elf-gcc", "PASS", gcc.string()});
221	    else
222	      rows.push_back({"riscv64-unknown-elf-gcc", "FAIL",
223	                      "missing " + gcc.string() +
224	                          " -- check HYBRID_TOOLCHAIN=" + tc});
225	  }
226	  return rows;
227	}
228	
229	// --- runtime ----------------------------------------------------------------
230	
231	constexpr long kDefaultJobs = 8;
232	
233	std::vector<Row> doctor_runtime() {
234	  std::vector<Row> rows;
235	  long nproc = sysconf(_SC_NPROCESSORS_ONLN);
236	  if (nproc < 1) nproc = 1;
237	  rows.push_back({"nproc", "INFO", std::to_string(nproc)});
238	
239	  std::error_code ec;
240	  if (fs::is_directory("/dev/shm", ec)) {
241	    struct statvfs vfs{};
242	    unsigned long long free_gb = 0;
243	    if (statvfs("/dev/shm", &vfs) == 0)
244	      free_gb = static_cast<unsigned long long>(vfs.f_bavail) * vfs.f_frsize /
245	                (1024ULL * 1024 * 1024);
246	    rows.push_back({"/dev/shm free", free_gb >= 4 ? "PASS" : "WARN",
247	                    std::to_string(free_gb) + " GB"});
248	  } else {
249	    rows.push_back({"/dev/shm", "WARN",
250	                    "not present -- e2e fixtures will fall back to $TMPDIR"});
251	  }
252	
253	  long suggested = std::min(nproc, kDefaultJobs);
254	  rows.push_back({"JOBS suggestion", "INFO",
255	                  std::to_string(suggested) + " (default cap = " +
256	                      std::to_string(kDefaultJobs) + ")"});
257	  return rows;
258	}
259	
260	// --- engines (C++-only readout, after Summary) ------------------------------
261	
262	// Reflects `list engines` from the same F2 discovery, in doctor's row idiom.
263	// INFO-tagged and printed after Summary, so it never moves the summary counts
264	// or the exit code. Discovery warnings surface as WARN rows here.
265	void print_engines_section() {
266	  Discovery disc = discover_engines();
267	  size_t w = 0;
268	  for (const EngineDescriptor& e : disc.engines) w = std::max(w, e.id.size());
269	
270	  std::printf("\nengines:\n");
271	  for (const EngineDescriptor& e : disc.engines)
272	    std::printf("  [INFO] %s  kind=%s vlen=%s triggers=%s\n",
273	                ljust(e.id, w).c_str(), e.kind.c_str(), vlen_str(e.vlen).c_str(),
274	                join(e.triggers).c_str());
275	  for (const std::string& warn : disc.warnings)
276	    std::printf("  [WARN] %s\n", warn.c_str());
277	}
278	
279	struct Section {
280	  const char* title;
281	  std::vector<Row> rows;
282	};
283	
284	}  // namespace
285	
286	int cmd_doctor(const Cli&) {
287	  std::vector<Section> sections = {
288	      {"artifacts", doctor_artifacts()},
289	      {"submodules", doctor_submodules()},
290	      {"toolchain", doctor_toolchain()},
291	      {"runtime", doctor_runtime()},
292	  };
293	
294	  size_t name_width = 0;
295	  for (const Section& s : sections)
296	    for (const Row& r : s.rows) name_width = std::max(name_width, r.name.size());
297	
298	  int passes = 0, fails = 0, warns = 0;
299	  for (const Section& s : sections) {
300	    std::printf("%s:\n", s.title);
301	    for (const Row& r : s.rows) {
302	      if (r.status == "PASS") ++passes;
303	      else if (r.status == "FAIL") ++fails;
304	      else if (r.status == "WARN") ++warns;
305	      std::printf("  [%-4s] %s  %s\n", r.status.c_str(),
306	                  ljust(r.name, name_width).c_str(), r.detail.c_str());
307	    }
308	    std::printf("\n");
309	  }
310	  std::printf("Summary: %d PASS, %d FAIL, %d WARN\n", passes, fails, warns);
311	
312	  print_engines_section();
313	  return fails > 0 ? 1 : 0;
314	}
315	
316	}  // namespace andes_sim
317

